 @keyframes sg-tiles{
  0%{opacity:0;transform:scale(.065) rotate(11deg);animation-timing-function:cubic-bezier(.13,.78,.32,1)}
  38%{opacity:1;transform:translate(-2px,-4px) scale(.82) rotate(2deg);animation-timing-function:ease-out}
  67%{opacity:.87}
  100%{opacity:0;transform:translate(-7px,12px) scale(1.07) rotate(-6deg)}
 }
 @keyframes sg-stars{
  0%{opacity:0;transform:scale(.12) rotate(-9deg);animation-timing-function:cubic-bezier(.15,.7,.2,1)}
  36%{opacity:.84;transform:translate(0,-11px) scale(.9) rotate(1deg);animation-timing-function:ease-out}
  68%{opacity:.77}
  100%{opacity:0;transform:translate(-8px,18px) scale(1.13) rotate(7deg)}
 }
}

/* Kubai 011 entrance and 015 quick-start handoff for the command palette. */
@media (prefers-reduced-motion: no-preference) {
  .dark [data-base-ui-portal]:has(> [data-slot="command-dialog-viewport"] > [data-slot="command-dialog-popup"][data-palette-mode="command"]) {
    --sg-palette-enter: cubic-bezier(0, 0, .58, 1);
    --sg-palette-exit: cubic-bezier(.32, .72, 0, 1);

    & :is([data-slot="command-dialog-popup"], [data-slot="command-dialog-backdrop"]) {
      transition-timing-function: var(--sg-palette-enter) !important;
    }

    & :is([data-slot="command-dialog-popup"], [data-slot="command-dialog-backdrop"])[data-ending-style] {
      transition-timing-function: var(--sg-palette-exit) !important;
      transition-duration: 65ms !important;
    }
  }
}

/* Keep the avatar ring inside the virtualized timeline row. */
[data-subagent-group] > [data-slot=collapsible-trigger] > span:first-child { padding-inline-start: 2px; }
